import sys, os, re, json, math
from datetime import datetime, timedelta

QUANTS = ["temp", "rh", "pres", "wspd", "wdir", "rain"]
RANGES = {"temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
          "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000)}
EPOCH = datetime(1970, 1, 1)
DIRECTIVE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")


def convert(q, unit, v):
    if unit.startswith("tips:") and q == "rain":
        return v * float(unit[5:])
    if q == "temp":
        if unit == "degF": return (v - 32) * 5 / 9
        if unit == "K": return v - 273.15
    elif q == "rh":
        if unit == "frac": return v * 100
    elif q == "pres":
        if unit == "kPa": return v * 10
        if unit == "inHg": return v * 33.8638866667
        if unit == "mmHg": return v * 1.33322387415
    elif q == "wspd":
        if unit == "kmh": return v / 3.6
        if unit == "kn": return v * 1852 / 3600
        if unit == "mph": return v * 0.44704
    return v


def is_missing(s):
    if s == "" or s == "---" or s.lower() == "nan":
        return True
    return re.fullmatch(r"-9999(\.0*)?", s) is not None


def parse_time(s):
    s = s.strip().replace("T", " ")
    return datetime.strptime(s, "%Y-%m-%d %H:%M:%S")


def secs(dt):
    return int((dt - EPOCH).total_seconds())


def parse_tz(s):
    s = s.strip()
    if s == "Z":
        return 0
    sign = -1 if s[0] == "-" else 1
    h, m = s[1:].split(":")
    return sign * (int(h) * 3600 + int(m) * 60)


def read_file(path):
    with open(path, "rb") as f:
        text = f.read().decode("utf-8")
    if text.startswith("\ufeff"):
        text = text[1:]
    hdr = {}
    columns = None
    units = {}
    rows = []   # (logger_time_secs, {q: value})
    syncs = []  # (logger_secs, ref_secs)
    for line in text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        line = line.strip()
        if not line:
            continue
        if line.startswith("#"):
            m = DIRECTIVE.match(line)
            if not m:
                continue
            key, val = m.group(1), m.group(2).strip()
            if key in ("station", "upload", "interval", "tz"):
                hdr[key] = val
            elif key == "columns":
                columns = [c.strip() for c in val.split(",")]
            elif key == "units":
                for pair in val.split():
                    if "=" in pair:
                        q, u = pair.split("=", 1)
                        units[q] = u
            elif key == "sync":
                parts = {}
                for p in val.split():
                    if "=" in p:
                        k, v = p.split("=", 1)
                        parts[k] = v
                if "logger" in parts and "ref" in parts:
                    # logger time may contain a space: re-parse
                    mm = re.search(r"logger=(\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d)", val)
                    syncs.append((secs(parse_time(mm.group(1))),
                                  secs(datetime.strptime(parts["ref"], "%Y-%m-%dT%H:%M:%SZ"))))
            continue
        fields = [x.strip() for x in line.split(",")]
        vals = {}
        t = None
        for c, x in zip(columns, fields):
            if c == "time":
                t = secs(parse_time(x))
            elif c in RANGES:
                if is_missing(x):
                    continue
                try:
                    v = float(x)
                except ValueError:
                    continue
                if math.isnan(v) or math.isinf(v):
                    continue
                v = convert(c, units.get(c, ""), v)
                lo, hi = RANGES[c]
                if lo <= v <= hi:
                    vals[c] = v
        rows.append((t, vals))
    return hdr, rows, syncs


def main(indir, outfile):
    stations = {}
    for name in sorted(os.listdir(indir)):
        p = os.path.join(indir, name)
        if not name.endswith(".log") or not os.path.isfile(p):
            continue
        hdr, rows, syncs = read_file(p)
        st = hdr.get("station")
        if st is None:
            continue
        off = parse_tz(hdr.get("tz", "Z"))
        up = int(hdr.get("upload", 0))
        S = stations.setdefault(st, {"interval": None, "samples": {}, "sync": {}})
        if hdr.get("interval") and S["interval"] is None:
            S["interval"] = int(float(hdr["interval"]))
        for t, vals in rows:
            u = t - off
            cur = S["samples"].get(u)
            if cur is None or up > cur[0]:
                S["samples"][u] = (up, vals)
        for lg, ref in syncs:
            u = lg - off
            cur = S["sync"].get(u)
            if cur is None or up > cur[0]:
                S["sync"][u] = (up, ref - u)

    out = []
    for st in sorted(stations):
        S = stations[st]
        if not S["samples"]:
            continue
        interval = S["interval"]
        pts = sorted((u, o) for u, (_, o) in S["sync"].items())

        def offset(t):
            if not pts:
                return 0
            if t <= pts[0][0]:
                return pts[0][1]
            if t >= pts[-1][0]:
                return pts[-1][1]
            lo, hi = 0, len(pts) - 1
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if pts[mid][0] <= t:
                    lo = mid
                else:
                    hi = mid
            (t1, o1), (t2, o2) = pts[lo], pts[hi]
            if t == t1:
                return o1
            return (o1 * (t2 - t1) + (o2 - o1) * (t - t1)) // (t2 - t1)

        recs = []
        for u, (_, vals) in S["samples"].items():
            c = u + offset(u)
            recs.append((c, u, vals))
        recs.sort(key=lambda r: (r[0], r[1]))

        def hour_of(c):
            return -((-c) // 3600)  # index of hour end, in hours

        h0, h1 = hour_of(recs[0][0]), hour_of(recs[-1][0])
        buckets = {h: [] for h in range(h0, h1 + 1)}
        for c, u, vals in recs:
            buckets[hour_of(c)].append((c, vals))

        # rain increments
        incr = {}
        prev = None
        for idx, (c, u, vals) in enumerate(recs):
            if "rain" not in vals:
                continue
            r = vals["rain"]
            if prev is not None and (c - prev[0]) * 2 <= 5 * interval:
                incr[idx] = r - prev[1] if r >= prev[1] else r
            prev = (c, r)
        # map increments into buckets
        hour_incr = {h: 0.0 for h in buckets}
        for idx, inc in incr.items():
            hour_incr[hour_of(recs[idx][0])] += inc

        expected = 3600 // interval
        hours = []
        for h in range(h0, h1 + 1):
            ts = (EPOCH + timedelta(hours=h)).strftime("%Y-%m-%dT%H:00:00Z")
            entry = {"hour": ts}
            rows = buckets[h]
            for q in QUANTS:
                xs = [v[q] for _, v in rows if q in v]
                n = len(xs)
                ok = n * 4 >= expected * 3 and n > 0
                val = None
                if ok:
                    if q == "rain":
                        val = hour_incr[h]
                    elif q == "wdir":
                        sx = sy = 0.0
                        k = 0
                        for _, v in rows:
                            if "wdir" in v and v.get("wspd", 0) > 0 and "wspd" in v:
                                a = math.radians(v["wdir"])
                                sx += math.sin(a)
                                sy += math.cos(a)
                                k += 1
                        if k:
                            val = math.degrees(math.atan2(sx, sy)) % 360
                    else:
                        val = math.fsum(xs) / n
                if val is not None:
                    val = round(val, 2)
                    if val >= 360:
                        val = 0.0
                    val = val + 0.0
                entry[q] = {"value": val, "n": n}
            hours.append(entry)
        out.append({"station": st, "interval_s": interval, "hours": hours})

    with open(outfile, "w") as f:
        json.dump({"stations": out}, f)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
